<script setup lang="ts">
// PT-04; FR-ASSET-001/003/004; D18-API-010/011/050/051/052; TC-ASSET-001/002/006/007/008
import {ref,reactive,computed,onMounted} from 'vue';import {useRouter} from 'vue-router';import {useAuthStore} from '../../stores/auth';import {get,command,errorText,type Row,type Page} from '../../api/implemented';import {classifications,assetStates,type Asset,type Source} from '../../api/asset';
const auth=useAuthStore(),router=useRouter(),send=command(),canWrite=computed(()=>auth.permissions.includes('asset:write'));
const rows=ref<Asset[]>([]),sources=ref<Source[]>([]),choices=ref<Source[]>([]),orgs=ref<Row[]>([]),owners=ref<Row[]>([]),error=ref(''),message=ref(''),busy=ref(false),page=ref(1),total=ref(0),sourcePage=ref(1),sourceTotal=ref(0),tab=ref('assets'),showCreate=ref(false),showSource=ref(false);
const filters=reactive({orgId:'',keyword:'',status:'',classification:''});const form=reactive({orgId:auth.user?.orgId||'',assetCode:'',name:'',classification:'INTERNAL',ownerId:'',sourceId:''});const source=reactive({orgId:auth.user?.orgId||'',code:'',sourceType:'MANUAL',endpointRef:'',credentialRef:''});const editing=ref<Source|null>(null);const edit=reactive({endpointRef:'',credentialRef:'',clearCredential:false,status:'ENABLED',reason:''});
function query(){return Object.fromEntries(Object.entries(filters).filter(([,v])=>v))}
async function load(){const x=await get<Page>('D18-API-010',{}, {...query(),page:String(page.value),size:'20'});rows.value=x.items as Asset[];total.value=x.total;const s=await get<Page>('D18-API-050',{}, {page:String(sourcePage.value),size:'20',...(filters.orgId?{orgId:filters.orgId}:{})});sources.value=s.items as Source[];sourceTotal.value=s.total}
async function options(){choices.value=(await get<Page>('D18-API-050',{}, {orgId:form.orgId,status:'ENABLED',size:'100'})).items as Source[];if(auth.permissions.includes('auth:read'))owners.value=(await get<Page>('D18-API-007',{}, {orgId:form.orgId,status:'ENABLED',size:'100'})).items;form.sourceId='';form.ownerId=''}
async function run(f:()=>Promise<unknown>){busy.value=true;error.value='';message.value='';try{await f()}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function create(){const x=await send<Asset>('D18-API-011',{}, {...form,ownerId:form.ownerId||null,sourceId:form.sourceId||null});showCreate.value=false;await router.push('/metadata?asset='+x.id)}
async function createSource(){await send('D18-API-051',{}, {...source,endpointRef:source.endpointRef||null,credentialRef:source.credentialRef||null});showSource.value=false;source.credentialRef='';message.value='来源已登记，未执行真实连接';await load();await options()}
function selectSource(s:Source){editing.value=s;edit.endpointRef=s.endpointRef||'';edit.status=s.status;edit.credentialRef='';edit.clearCredential=false;edit.reason=''}
async function saveSource(){if(!editing.value)return;await send('D18-API-052',{id:editing.value.id},{expectedVersion:editing.value.version,endpointRef:edit.endpointRef||null,credentialRef:edit.clearCredential?'':edit.credentialRef||null,status:edit.status,reason:edit.reason});editing.value=null;await load();message.value='来源信息已更新'}
onMounted(()=>run(async()=>{await load();if(canWrite.value){if(auth.permissions.includes('auth:read'))orgs.value=await get<Row[]>('D18-API-005');await options()}}));
</script><template><section><h2>数据资产目录</h2><p>维护资产责任、分类和字段元数据。发布前需明确责任人并登记至少一个字段。</p><p role="alert" class="error">{{error}}</p><p role="status">{{message}}</p><div class="actions"><button @click="tab='assets'">资产目录</button><button @click="tab='sources'">数据来源</button><button v-if="canWrite&&tab==='assets'" @click="showCreate=!showCreate">新增资产</button><button v-if="canWrite&&tab==='sources'" @click="showSource=!showSource">登记来源</button></div><form class="actions" @submit.prevent="page=1;sourcePage=1;run(load)"><label>资产名称或代码<input v-model="filters.keyword" placeholder="搜索资产"></label><label>资产状态<select v-model="filters.status"><option value="">全部</option><option v-for="(label,key) in assetStates" :key="key" :value="key">{{label}}</option></select></label><label>分类<select v-model="filters.classification"><option value="">全部</option><option v-for="(label,key) in classifications" :key="key" :value="key">{{label}}</option></select></label><button :disabled="busy">查询</button></form><form v-if="showCreate" @submit.prevent="run(create)"><h3>新增资产草稿</h3><div class="columns"><label>所属组织<select v-model="form.orgId" @change="run(options)"><option v-for="o in orgs" :key="o.id" :value="o.id">{{o.name}}</option></select></label><label>资产代码<input v-model="form.assetCode" required maxlength="64" pattern="[A-Za-z][A-Za-z0-9_.-]*"></label><label>资产名称<input v-model="form.name" required maxlength="128"></label><label>分类<select v-model="form.classification"><option v-for="(label,key) in classifications" :key="key" :value="key">{{label}}</option></select></label><label>责任人<select v-model="form.ownerId"><option value="">草稿暂不指定</option><option v-for="u in owners" :key="u.id" :value="u.id">{{u.displayName}} / {{u.username}}</option></select></label><label>数据来源<select v-model="form.sourceId"><option value="">未关联来源</option><option v-for="s in choices" :key="s.id" :value="s.id">{{s.code}} · {{s.sourceType}}</option></select></label></div><button :disabled="busy">保存并登记字段</button></form><template v-if="tab==='assets'"><table><thead><tr><th>资产名称 / 代码</th><th>状态</th><th>分类</th><th>责任人</th><th>来源</th><th>字段数</th></tr></thead><tbody><tr v-for="a in rows" :key="a.id"><td><RouterLink :to="'/metadata?asset='+a.id">{{a.name}}</RouterLink><br>{{a.assetCode}}</td><td>{{assetStates[a.status]}}</td><td>{{classifications[a.classification]||a.classification}}</td><td>{{a.ownerName||'未指定'}}</td><td>{{a.sourceCode||'未关联'}}</td><td>{{a.fieldCount}}</td></tr></tbody></table><p v-if="!rows.length&&!busy">没有符合条件的资产。</p><div class="actions"><button :disabled="page<=1||busy" @click="page--;run(load)">上一页</button>第{{page}}页 · 共{{total}}项<button :disabled="page*20>=total||busy" @click="page++;run(load)">下一页</button></div></template><template v-else><p>来源登记只记录元信息；MYSQL来源的配置引用不代表已建立连接或完成采集。</p><form v-if="showSource" @submit.prevent="run(createSource)"><h3>登记来源</h3><div class="columns"><label>组织<select v-model="source.orgId"><option v-for="o in orgs" :key="o.id" :value="o.id">{{o.name}}</option></select></label><label>来源代码<input v-model="source.code" required maxlength="64" pattern="[A-Za-z][A-Za-z0-9_.-]*"></label><label>来源类型<select v-model="source.sourceType"><option value="MANUAL">手工登记</option><option value="MYSQL">MySQL元信息</option></select></label><label>连接配置引用<input v-model="source.endpointRef" :required="source.sourceType==='MYSQL'" placeholder="仅逻辑名称，不填密码或带参数URL"></label><label>凭证配置引用<input v-model="source.credentialRef" placeholder="仅填写秘密存储中的引用名称"></label></div><button :disabled="busy">登记</button></form><table><thead><tr><th>来源代码</th><th>类型</th><th>状态</th><th>凭证配置</th><th>操作</th></tr></thead><tbody><tr v-for="s in sources" :key="s.id"><td>{{s.code}}</td><td>{{s.sourceType}}</td><td>{{s.status==='ENABLED'?'启用':'停用'}}</td><td>{{s.credentialConfigured?'已登记引用':'未配置'}}</td><td><button v-if="canWrite" @click="selectSource(s)">维护</button></td></tr></tbody></table><div class="actions"><button :disabled="sourcePage<=1||busy" @click="sourcePage--;run(load)">上一页</button>第{{sourcePage}}页 · 共{{sourceTotal}}项<button :disabled="sourcePage*20>=sourceTotal||busy" @click="sourcePage++;run(load)">下一页</button></div><form v-if="editing" @submit.prevent="run(saveSource)"><h3>维护来源 {{editing.code}}</h3><label>连接配置引用<input v-model="edit.endpointRef"></label><label>新凭证引用<input v-model="edit.credentialRef" placeholder="留空保留已有引用"></label><label class="check"><input type="checkbox" v-model="edit.clearCredential">清除已有凭证引用</label><label>状态<select v-model="edit.status"><option>ENABLED</option><option>DISABLED</option></select></label><label>变更原因<textarea v-model="edit.reason" required maxlength="1000"/></label><button :disabled="busy">保存</button><button type="button" @click="editing=null">取消</button></form></template></section></template>